changeSet.sql:
ALTER TABLE clinlims.alert ADD COLUMN IF NOT EXISTS upgrade_stashed_alert_type VARCHAR(50);
UPDATE clinlims.alert
   SET upgrade_stashed_alert_type = alert_type,
       alert_type = 'OTHER'
 WHERE alert_type NOT IN (
    'FREEZER_TEMPERATURE', 'EQUIPMENT_FAILURE', 'INVENTORY_LOW', 'SAMPLE_TRACKING', 'OTHER',
    'EQA_DEADLINE', 'SAMPLE_EXPIRATION', 'STAT_UPCOMING', 'STAT_OVERDUE', 'CRITICAL_UNACKNOWLEDGED'
 );
